theorem homogeneous_eval_coordinate (p : MvPolynomial σ R) {e : ℕ}
    (hp : p.IsHomogeneous e) (i : σ) :
    MvPolynomial.eval (Pi.single i 1) p = p.coeff (Finsupp.single i e)

theorem comp {η : P → (E'' →L[K] E') × (F' →L[K] F'')}
    (hη : IsAdmissibleOn k η s) (hγ : IsAdmissibleOn k γ s) :
    IsAdmissibleOn k (fun x => alternatingMorphismComp (η x) (γ x)) s

theorem reparam (hγ : IsAdmissibleOn k γ s) {f : Q → P}
    (hf : AnalyticOnNhd K f t) (hfs : Set.MapsTo f t s) :
    IsAdmissibleOn k (γ ∘ f) t

theorem prod_word_eq_prod_pow {ι : Type*} [Fintype ι] [DecidableEq ι] {n : ℕ}
    (w : ι → K) (f : Fin n → ι) :
    ∏ r, w (f r) = ∏ j, w j ^ (wordCount f j : ℕ)

theorem diagonal_eq_of_hasFPowerSeriesAt (j : W →ₗᵢ[K] Z) {f : P → W} {x₀ : P}
    {b : FormalMultilinearSeries K P Z} {p : FormalMultilinearSeries K P W}
    (hb : HasFPowerSeriesAt (j ∘ f) b x₀) (hp : HasFPowerSeriesAt f p x₀) (n : ℕ) (h : P) :
    j (p n (fun _ => h)) = b n (fun _ => h)

theorem eq_sum_of_hasFiniteFPowerSeriesOnBall_zero {g : H → W}
    {p : FormalMultilinearSeries K H W} {N : ℕ} (hg : HasFiniteFPowerSeriesOnBall g p 0 N ⊤)
    (x : H) : g x = ∑ n ∈ Finset.range N, p n (fun _ => x)

theorem compLinearMap_tupleMap_apply {N' : Type*} [AddCommGroup N'] [Module R N'] {ι : Type*}
    {N : ℕ} (F : M [⋀^ι]→ₗ[R] N') (v : Fin N → M) (τ : ι → Fin N) :
    F.compLinearMap (tupleMap v) (fun i => Pi.single (τ i) (1 : R)) = F (v ∘ τ)

theorem compLinearMap_tupleMap_apply_self {N' : Type*} [AddCommGroup N'] [Module R N'] {N : ℕ}
    (F : M [⋀^Fin N]→ₗ[R] N') (v : Fin N → M) :
    F.compLinearMap (tupleMap v) (fun i => Pi.single i (1 : R)) = F v

theorem alternatingMap_sum_apply {N : Type*} [AddCommGroup N] [Module R N] {ι κ : Type*}
    (s : Finset κ) (f : κ → M [⋀^ι]→ₗ[R] N) (v : ι → M) :
    (∑ j ∈ s, f j) v = ∑ j ∈ s, f j v

theorem append_prefix_of_mem_range {j : L} {s : ℕ → List L}
    (hs : ∀ r, s r ++ [j] <+: s (r + 1)) {w₁ w₂ : List L} (h₁ : w₁ ∈ Set.range s)
    (h₂ : w₂ ∈ Set.range s) (hne : w₁ ≠ w₂) : w₁ ++ [j] <+: w₂ ∨ w₂ ++ [j] <+: w₁

theorem exists_extension_forall_mem {j : L} {a : Set (List L)}
    (ha : ∀ T : Set (List L), IsLabelChain j T → (T \ a).Finite) (t : List L) :
    ∃ s, t <+: s ∧ ∀ u, s ++ [j] <+: u → u ∈ a

theorem detV'_eq_zero_of_mem {P : Submodule K (Fin (k + 1) → K) × Submodule K (Fin k → K)}
    (hP : P ∈ pairFamily K k) (z : Fin k → Fin k → K) (hz : ∀ r, z r ∈ P.2) :
    detV' K k z = 0

theorem IsChainSeq.eventually_notMem_range {j h : L} (hjh : j ≠ h) {s s' : ℕ → List L}
    (hs : IsChainSeq j s) (hs' : IsChainSeq h s') :
    ∀ᶠ n in atTop, s' n ∉ Set.range s

theorem tendsto_cofinite_of_supported {f : List L → V} {s : ℕ → List L}
    (hsupp : ∀ w, w ∉ Set.range s → f w = 0)
    (hf : Tendsto (fun n => f (s n)) atTop (𝓝 0)) : Tendsto f cofinite (𝓝 0)

theorem alternatizeUncurryFin_smulRight_eq_zero {ν : (Fin (k + 1) → κ) →ₗ[κ] κ}
    {α : (Fin (k + 1) → κ) [⋀^Fin k]→ₗ[κ] κ}
    (hα : ∀ ξ : Fin k → (Fin (k + 1) → κ), (∀ r, ξ r ∈ LinearMap.ker ν) → α ξ = 0)
    (x : Fin (k + 1) → (Fin (k + 1) → κ)) (i₀ : Fin (k + 1))
    (hx : ∀ j, j ≠ i₀ → ν (x j) = 0) :
    AlternatingMap.alternatizeUncurryFin (ν.smulRight α) x = 0

theorem evalFirst_targetForm_comp_swap (h2 : FibreCondition2 κ k τ) {a : Fin k → Fin k}
    (ha : Injective a) {i j : Fin k} (hij : i ≠ j) (ψ : Fin k → ((Fin (k + 1) → κ) →ₗ[κ] κ)) :
    evalFirst (targetForm τ (a ∘ Equiv.swap i j) ψ) = -evalFirst (targetForm τ a ψ)

theorem evalFirst_targetForm_eq_zero (h2 : FibreCondition2 κ k τ) {a : Fin k → Fin k} {s : Fin k}
    (hs : ∀ r, a r ≠ s) (ψ : Fin k → ((Fin (k + 1) → κ) →ₗ[κ] κ)) :
    evalFirst (targetForm τ a ψ) = 0

theorem update_sum (hΦ : IsBddML Φ C) (u : Fin d → Linf 𝕜) (j : Fin d) {ι : Type*}
    (s : Finset ι) (f : ι → Linf 𝕜) :
    Φ (Function.update u j (∑ i ∈ s, f i)) = ∑ i ∈ s, Φ (Function.update u j (f i))

theorem exists_pairFamily_transfer {P : Submodule F (Fin (k + 1) → F) × Submodule F (Fin k → F)}
    (hP : P ∈ pairFamily F k) {g : Fin k → ((Fin (k + 1) → F) →ₗ[F] (Fin k → F))}
    (hg : ∀ r, P.1.map (g r) ≤ P.2) {ξ : Fin k → (Fin (k + 1) → F)} (hξ : ∀ r, ξ r ∈ P.1) :
    ∃ j ∈ pairFamily K k, (∀ r, j.1.map (bcMap (K := K) (g r)) ≤ j.2) ∧
      ∀ r, (incl (ξ r) : Fin (k + 1) → K) ∈ j.1
